sys_ui_action.script:
(function() {
    if (!gs.hasRole('sn_customerservice_manager')) {
        gs.addErrorMessage('Only a manager can do this.');
        return;
    }
    if (current.getValue('manager_signoff_status') != 'pending') {
        gs.addErrorMessage('This claim is not waiting on sign-off.');
        return;
    }
    var reason = current.getValue('manager_reason');
    if (!reason) {
        gs.addErrorMessage('Please type a reason in the Manager Reason field before declining.');
        return;
    }

    current.setValue('manager_signoff_status', 'declined');
    current.setValue('manager_signoff_by', gs.getUserID());
    current.setValue('manager_notes', reason);
    current.update();

    var cs = new GlideRecord('sn_customerservice_case');
    if (current.getValue('customer_case') && cs.get(current.getValue('customer_case'))) {
        cs.work_notes = 'Manager ' + gs.getUserDisplayName() +
            ' declined to approve this claim. Reason: ' + reason +
            '. Adjuster should revise the recommendation.';
        cs.update();
    }

    gs.addInfoMessage('Sign-off declined. Reason recorded for the adjuster.');
    action.setRedirectURL(current);
})();
